/** A03-R00-SISMEN (241 bytes): configuración mensual por sistema. */
public record SistemaMensualExport(
        int sistema, int modSis, int resCsi, int tipBd,
        int numCicDia, int numCicMes,
        String nomBdSal, int staBdSal,
        String nomBdMovHi,
        long secOkHi, long secInfHi, long secErrHi,   // 9(10) COMP
        int staBdMovHi,
        List<CicloMensual> ciclos) {                  // OCCURS 5, se llenan min(5, numCicMes)

    /** A03-R00-CTL-MEN. AAMM pasó de 9(04) a 9(06) con Cronos 2000 (CCAAMM). */
    public record CicloMensual(String nomBdMov, int numBdMov, YearMonth aamm,
                               long secOk, long secInf, long secErr, int staBdMov) {}

    public SistemaMensualExport {
