# application.yml
p195:
  usuario: S151
  familia: CMEMP                       # " ON CMEMP." en los seis WKS-NOMARCH-*
  patron: "({usuario}){usuario}/FILE/{dataset}/{fecha} ON {familia}."
  datasets: [B01SISDIA, B02ARCINTER, B03SISMEN, B04SISTEM, B05PROCESOS, B09CONXSIS]

// ---------------------------------------------------------------------------
@ConfigurationProperties("p195")
public record P195Properties(String usuario, String familia, String patron, List<String> datasets) {

    /** Un solo patrón sustituye los seis grupos 01 WKS-NOMARCH-B0x. */
    public String titulo(String dataset, FechaRotulado f) {
        return patron.replace("{usuario}", usuario)
                     .replace("{dataset}", dataset)
                     .replace("{fecha}", f.aammdd())
                     .replace("{familia}", familia);
    }
}

/** Fecha que rotula los seis archivos (AAMMDD). Ceros si B01SISDIA está vacío. */
public record FechaRotulado(LocalDate fecha) {

    private static final DateTimeFormatter AAMMDD = DateTimeFormatter.ofPattern("yyMMdd");

    public String aammdd() { return fecha == null ? "000000" : fecha.format(AAMMDD); }

    /**
     * 02-00100-GENERA-B01SISDIA, rama NOT OLDCODE: B01-SIS-FECPRO viene en CCAAMMDD
     * y A2K-CONV-CAMD-TO-AMD descarta el siglo. Se toma del PRIMER registro de B01,
     * sea cual sea su sistema.
     */
    public static FechaRotulado dePrimerRegistro(Optional<SistemaDiario> primero) {
        return new FechaRotulado(primero
                .map(b01 -> LocalDate.parse(String.format("%08d", b01.fecPro()),
                                            DateTimeFormatter.BASIC_ISO_DATE))
                .orElse(null));
    }
}

@Bean
Job extraeControlS151(JobRepository repo, ControlEjecucionDecider yaTerminado,
                      Step exportaB01, Step exportaB02, Step exportaB03,
                      Step exportaB04, Step exportaB05, Step exportaB09,
                      Step marcaTerminado) {
    Flow exportacion = new FlowBuilder<SimpleFlow>("exportacion")
            .start(exportaB01)          // calcula también la FechaRotulado
            .next(exportaB02).next(exportaB03).next(exportaB04)
            .next(exportaB05)           // mismo orden del fuente: B05 antes que B09
            .next(exportaB09)
            .next(marcaTerminado)       // solo hace algo en Alta Disponibilidad
            .build();

    return new JobBuilder("S151P195", repo)
            .start(yaTerminado).on("YA_TERMINADO").end()      // 08-02000-FINALIZA-PROGRAMA
            .from(yaTerminado).on("*").to(exportacion)
            .end()
            .build();
}

@Component
@RequiredArgsConstructor
public class ControlEjecucionDecider implements JobExecutionDecider {

    private static final int SISTEMA = 151, NUM_PROCESO = 195;
    private final ProcesosClient b05;            // "B05PROCESOS IN S151-L001": func 01, 19, 37

    @Override
    public FlowExecutionStatus decide(JobExecution je, StepExecution se) {
        if (!je.getJobParameters().getString("altaDisponibilidad", "N").equals("S")) {
            return FlowExecutionStatus.COMPLETED;              // W77-VALUE distinto de 1
        }
        LocalDate fecha = FechaProceso.de(je);                // CONSISDIA del sistema 151
        return b05.consulta(SISTEMA, fecha, NUM_PROCESO)       // función 01
                .map(r -> r.staPgm() == 0
                        ? FlowExecutionStatus.COMPLETED        // existe pendiente: regenera
                        : new FlowExecutionStatus("YA_TERMINADO"))
                .orElseGet(() -> {
                    b05.alta(SISTEMA, fecha, NUM_PROCESO);     // función 19; si falla, lanza excepción
                    return FlowExecutionStatus.COMPLETED;
                });
    }
}

/** 08-01200-ACTUALIZA-B05: función 37 con STAPGM = 1 al terminar. */
@Bean
Tasklet marcaTerminado(ProcesosClient b05) {
    return (c, ctx) -> {
        b05.cambiaEstatus(151, FechaProceso.de(ctx), 195, 1);
        return RepeatStatus.FINISHED;
    };
}

@Component
@RequiredArgsConstructor
public class VolcadoDatasetStepFactory {

    private final JobRepository repo;
    private final PlatformTransactionManager tx;
    private final DataSource controlS151;          // réplica relacional de S151BD99CONTROL (solo lectura)
    private final P195Properties props;

    /** Un step por dataset: recorre todo y escribe el registro tal cual (MOVE dataset TO registro). */
    public <T> Step volcado(String dataset, RowMapper<T> mapper, LineAggregator<T> formato,
                            FechaRotulado fecha) {
        var lector = new JdbcCursorItemReaderBuilder<T>()
                .name(dataset).dataSource(controlS151)
                .sql("SELECT * FROM " + dataset + " ORDER BY ID")   // orden físico del dataset
                .rowMapper(mapper)
                .build();
        var escritor = new FlatFileItemWriterBuilder<T>()
                .name(dataset + "Writer")
                .resource(new FileSystemResource(props.titulo(dataset, fecha)))
                .lineAggregator(formato)                            // layout fijo, sin separadores
                .shouldDeleteIfEmpty(false)                         // el fuente deja el archivo vacío
                .build();
        return new StepBuilder("volcado" + dataset, repo)
                .<T, T>chunk(500, tx).reader(lector).writer(escritor)
                .build();
    }
}

/** 04-00110-VACIA-B03SISMEN + 04-00111-BASES-CICLO. */
@Component
@RequiredArgsConstructor
public class SistemaMensualProcessor implements ItemProcessor<SistemaMensualB03, SistemaMensualExport> {

    private final P195Properties props;   // p195.b03.corregir-secerrhi: false

    @Override
    public SistemaMensualExport process(SistemaMensualB03 b) {
        int n = Math.min(5, b.numCicMes());                      // UNTIL IND > 5 OR IND > NUMCICMES
        List<CicloMensual> ciclos = b.ciclos().subList(0, n);   // los demás quedan en blanco

        // Línea 1057: MOVE B03-SIS-SECERRHI TO A03-R00-SECINFHI. En el archivo actual el
        // campo SECINFHI lleva el valor de SECERRHI y SECERRHI nunca se escribe.
        long secInfHi = props.b03().corregirSecerrhi() ? b.secInfHi() : b.secErrHi();
        long secErrHi = props.b03().corregirSecerrhi() ? b.secErrHi() : 0L;   // ver riesgo

        return new SistemaMensualExport(b.sistema(), b.modSis(), b.resCsi(), b.tipBd(),
                b.numCicDia(), b.numCicMes(), b.nomBdSal(), b.staBdSal(), b.nomBdMovHi(),
                b.secOkHi(), secInfHi, secErrHi, b.staBdMovHi(), ciclos);
    }
}

/** 01-00100-ABRE-ENTRADA: la falla al abrir sí termina la tarea (STATUS := -1). */
@Component
class AperturaControlListener implements JobExecutionListener {
    @Override
    public void beforeJob(JobExecution je) {
        if (!controlS151.disponible()) {
            throw new IllegalStateException("TERMINACION ANORMAL DE PROCESO");
        }
    }
}

/** 900000-CHE-STA: en el fuente solo escribe en LJ; aquí falla el step. */
@Component
class ErrorDmsiiTranslator {
    RuntimeException traduce(DataAccessException e, String dataset) {
        return new VolcadoIncompletoException(
                "BASE DATOS S151BD99CONTROL ERROR EN BD " + e.getMessage() + " ESTRUCTURA " + dataset, e);
    }
}
